WHERE c.pool_type = 1

    AND c.customer_name LIKE CONCAT('%', #{customer.customerName}, '%')


    AND c.phone LIKE CONCAT('%', #{customer.phone}, '%')


    AND c.customer_stage = #{customer.customerStage}

${customer.params.dataScope}
ORDER BY c.last_followup_time DESC, c.id DESC

